<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><meta name="referrer" content="strict-origin-when-cross-origin"><title>Your Cerberus inspection report</title>
<style>:root{--ink:#1a252a;--navy:#182329;--gold:#c3a25c;--paper:#f4f1e8;--muted:#687176;--line:#e5e0d4}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.5 Inter,ui-sans-serif,system-ui,sans-serif}.masthead{background:var(--navy);color:white;padding:18px max(20px,calc((100vw - 760px)/2))}.brand{font-size:21px;font-weight:850;letter-spacing:.16em}.tag{display:block;color:#d1bb83;font-size:10px;letter-spacing:.13em}.wrap{max-width:800px;margin:28px auto;padding:0 20px}.card{background:white;border:1px solid var(--line);border-radius:12px;padding:clamp(18px,3vw,30px);box-shadow:0 8px 30px #17222909}.eyebrow{color:#90763c;text-transform:uppercase;letter-spacing:.15em;font-size:11px;font-weight:800}.card h1{font-size:clamp(26px,4vw,36px);line-height:1.12;margin:9px 0}.muted{color:var(--muted)}.vehicle{background:#f5f3ed;border-radius:8px;padding:12px;margin:16px 0}.vehicle span{display:block;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em}.download{display:inline-block;background:var(--gold);color:var(--navy);font-weight:800;text-decoration:none;border-radius:7px;padding:12px 18px;margin:5px 0 14px}.scorecard{display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:7px;margin:16px 0}.score{border-left:4px solid var(--score-color);background:#f6f5f1;padding:8px 10px;border-radius:4px}.score strong{display:block;font-size:16px}.score span{font-size:11px;color:var(--muted)}.video{margin-top:18px}.video h2{font-size:17px}.player{aspect-ratio:16/9;width:100%;border:0;border-radius:8px;background:#101820}.link{color:#6c5830}.foot{margin-top:18px;font-size:12px;color:var(--muted)}@media(max-width:600px){.wrap{margin:22px auto}.masthead{padding:19px 20px}}</style></head>
  <body><header class="masthead"><img src="{{ asset('images/cerberus-logo.jpg') }}" alt="Cerberus logo" style="width:48px;height:48px;object-fit:contain;border-radius:50%;margin-right:14px"><div><span class="brand">CERBERUS</span><span class="tag">PRE-PURCHASE VEHICLE INSPECTION REPORT</span></div></header><main class="wrap"><section class="card">@if($report->inspection->package_snapshot['is_demo'] ?? false)<div class="score" style="--score-color:#bb913d"><strong>DEMO REPORT</strong><span>Sample data — not for customer use</span></div>@endif<div class="eyebrow">Inspection complete</div><h1>Your vehicle inspection report is ready.</h1><p class="muted">The inspection was completed {{ $report->inspection->completed_at?->format('j F Y') }}. Download the full Cerberus report below.</p>@if (session('email_delivery_failed'))<p class="muted">Your report is available here, but an email notification could not be sent. Please contact Cerberus if you need help.</p>@endif<div class="vehicle"><span>Vehicle</span><strong>{{ trim(($report->inspection->booking->vehicle->year ? $report->inspection->booking->vehicle->year.' ' : '').($report->inspection->booking->vehicle->make ?? '').' '.($report->inspection->booking->vehicle->model ?? '')) ?: 'Vehicle inspection' }}</strong><br>{{ $report->inspection->booking->vehicle->registration }} · {{ $report->inspection->booking->package->name }}</div><h2>Inspection results at a glance</h2><div class="scorecard">@foreach ($ratingCounts as $rating)<div class="score" style="--score-color:{{ $rating['color'] }}"><strong>{{ $rating['count'] }}</strong><span>{{ $rating['label'] }}</span></div>@endforeach</div><a class="download" href="{{ route('customer-reports.download', $token) }}">Download PDF report</a><div class="muted">Report version {{ $report->version }} · Generated {{ $report->generated_at->format('j M Y') }}</div>
      @if (strtolower((string) ($report->inspection->package_snapshot['code'] ?? '')) === 'gold' && ($report->inspection->package_snapshot['video_included'] ?? false) && $report->inspection->video)<section class="video"><h2>Inspection video</h2><iframe class="player" src="https://www.youtube-nocookie.com/embed/{{ $report->inspection->video->video_id }}?origin={{ urlencode(rtrim(url('/'), '/')) }}&autoplay=1&mute=1&playsinline=1&rel=0" title="Cerberus inspection video" referrerpolicy="strict-origin-when-cross-origin" allow="autoplay; accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe><p class="muted">If the embedded player is unavailable, <a class="link" href="{{ $report->inspection->video->source_url }}" target="_blank" rel="noopener noreferrer">open this video on YouTube</a>. Playback depends on the video owner’s embedding permissions and browser autoplay settings.</p></section>@endif
